import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import AppShell from './AppShell';
import { getHistory } from '../services/api';

export default function Dashboard() {
  const navigate = useNavigate();
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const storedUser = localStorage.getItem('user');
  const user = storedUser ? JSON.parse(storedUser) : null;

  useEffect(() => {
    let isMounted = true;

    const fetchHistory = async () => {
      setLoading(true);
      setError('');
      try {
        const response = await getHistory();
        if (isMounted) {
          setHistory(Array.isArray(response) ? response : []);
        }
      } catch (fetchError) {
        if (fetchError.message === 'Missing authentication token') {
          navigate('/login');
          return;
        }
        if (isMounted) {
          setError(fetchError.message || 'Failed to fetch data');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    fetchHistory();
    return () => {
      isMounted = false;
    };
  }, [navigate]);

  const metrics = useMemo(() => {
    const lastEntry = history[0];
    const averageSleep = history.length
      ? history.reduce((sum, item) => sum + Number(item.input_data?.sleep || 0), 0) / history.length
      : 0;

    const recentDates = new Set(
      history
        .filter((item) => {
          const created = new Date(item.created_at);
          const diff = Date.now() - created.getTime();
          return diff <= 7 * 24 * 60 * 60 * 1000;
        })
        .map((item) => new Date(item.created_at).toDateString())
    );

    return {
      lastScore: lastEntry ? Number(lastEntry.score).toFixed(2) : '--',
      averageSleep: averageSleep ? `${averageSleep.toFixed(1)}h` : '0h',
      weeklyActivity: `${recentDates.size} days`,
    };
  }, [history]);

  return (
    <AppShell
      title={`Welcome back, ${user?.name || 'User'}`}
      subtitle="Here is your health overview and your fastest path to a new prediction."
    >
      {loading ? <div className="empty-state">Loading...</div> : null}
      {!loading && error ? <div className="empty-state">{error || 'Failed to fetch data'}</div> : null}

      {!loading && !error ? (
        <>
          <div className="stats-grid">
            <div className="stat-card">
              <div className="card-icon icon-orange">?</div>
              <p className="stat-value">{metrics.lastScore}</p>
              <div className="stat-label">Last score</div>
            </div>
            <div className="stat-card">
              <div className="card-icon icon-teal">?</div>
              <p className="stat-value">{metrics.averageSleep}</p>
              <div className="stat-label">Average sleep</div>
            </div>
            <div className="stat-card">
              <div className="card-icon icon-purple">?</div>
              <p className="stat-value">{metrics.weeklyActivity}</p>
              <div className="stat-label">Weekly activity</div>
            </div>
          </div>

          <h2 className="section-title">Quick Actions</h2>
          <div className="action-grid">
            <button type="button" className="action-card" onClick={() => navigate('/predict')}>
              <div className="card-icon icon-teal">?</div>
              <h3>Predict Health Score</h3>
              <p>Enter today&apos;s habits and let your ML model estimate your current health score.</p>
              <span className="card-arrow">?</span>
            </button>
            <button type="button" className="action-card" onClick={() => navigate('/history')}>
              <div className="card-icon icon-purple">?</div>
              <h3>View History</h3>
              <p>Review previous scores, sleep trends, and habit snapshots stored in MongoDB.</p>
              <span className="card-arrow">?</span>
            </button>
            <button type="button" className="action-card" onClick={() => navigate('/chat')}>
              <div className="card-icon icon-orange">?</div>
              <h3>Open Chatbot</h3>
              <p>Ask simple questions about sleep, water, exercise, and healthier daily routines.</p>
              <span className="card-arrow">?</span>
            </button>
          </div>
        </>
      ) : null}
    </AppShell>
  );
}
